<?php require_once __DIR__.'/../../app/layout.php';$m=require_member();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$photo=upload('photo')?:$m['photo'];$pdo->prepare('UPDATE members SET full_name=?,mobile=?,address=?,district=?,state=?,pin=?,occupation=?,photo=? WHERE id=?')->execute([trim($_POST['full_name']),preg_replace('/\D/','',$_POST['mobile']),trim($_POST['address']),trim($_POST['district']),trim($_POST['state']),trim($_POST['pin']),trim($_POST['occupation']),$photo,$m['id']]);flash('Profile updated.');redirect('/member/profile.php');}header_html('Profile');?><h1>Your profile</h1><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=csrf()?>"><label>Name<input name="full_name" value="<?=e($m['full_name'])?>" required></label><label>Mobile<input name="mobile" value="<?=e($m['mobile'])?>" required></label><label>Email<input value="<?=e($m['email'])?>" disabled></label><label>Photograph<input type="file" name="photo"></label><label>Address<textarea name="address"><?=e($m['address'])?></textarea></label><label>District<input name="district" value="<?=e($m['district'])?>"></label><label>State<input name="state" value="<?=e($m['state'])?>"></label><label>PIN<input name="pin" value="<?=e($m['pin'])?>"></label><label>Occupation<input name="occupation" value="<?=e($m['occupation'])?>"></label><button>Save profile</button></form><?php footer_html();
